import{_ as o,o as e,c as n,a2 as r}from"./chunks/framework.CqdVOxXJ.js";const s="/rakkii-cars-guide/screenshots/11-hr-payroll-kiosk-announcements-documents/02-clock-kiosk.png",a="/rakkii-cars-guide/screenshots/11-hr-payroll-kiosk-announcements-documents/03-leave-approvals.png",i="/rakkii-cars-guide/screenshots/11-hr-payroll-kiosk-announcements-documents/01-payroll-register.png",y=JSON.parse('{"title":"11. HR, payroll, kiosk clock, announcements & documents","description":"","frontmatter":{},"headers":[],"relativePath":"chapters/11-hr-payroll-kiosk-announcements-documents.md","filePath":"chapters/11-hr-payroll-kiosk-announcements-documents.md","lastUpdated":1793268728000}'),l={name:"chapters/11-hr-payroll-kiosk-announcements-documents.md"};function g(d,t,c,h,p,m){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="_11-hr-payroll-kiosk-clock-announcements-documents" tabindex="-1">11. HR, payroll, kiosk clock, announcements &amp; documents <a class="header-anchor" href="#_11-hr-payroll-kiosk-clock-announcements-documents" aria-label="Permalink to &quot;11. HR, payroll, kiosk clock, announcements &amp; documents&quot;">​</a></h1><p><strong>For:</strong> Shop Owner · <strong>Hub:</strong> HR (<code>/hr</code>)</p><table tabindex="0"><thead><tr><th>Page</th><th>Path</th><th>Use</th></tr></thead><tbody><tr><td>Directory</td><td><code>/hr/employee-directory</code></td><td>Employee records, pay, loans, documents, scorecards, leave, history</td></tr><tr><td>Attendance</td><td><code>/hr/attendance</code></td><td>Punch register, off-site approvals, overtime approvals</td></tr><tr><td>Leave approvals</td><td><code>/hr/leave</code></td><td>Decide leave, set allotments, team balances</td></tr><tr><td>Clock kiosk</td><td><code>/hr/clock-kiosk</code></td><td>Shared tablet clock-in</td></tr><tr><td>Documents</td><td><code>/hr/documents</code></td><td>NTE, NOD, warning letter, quitclaim, BIR 2316</td></tr><tr><td>Payroll</td><td><code>/hr/payroll</code></td><td>Period register, overrides, 13th month, lock</td></tr><tr><td>Announcements</td><td><code>/hr/announcements</code></td><td>Shop memos on staff dashboards</td></tr></tbody></table><h2 id="_11-1-employee-directory-hr-employee-directory" tabindex="-1">11.1 Employee Directory (<code>/hr/employee-directory</code>) <a class="header-anchor" href="#_11-1-employee-directory-hr-employee-directory" aria-label="Permalink to &quot;11.1 Employee Directory (`/hr/employee-directory`)&quot;">​</a></h2><p>The subtitle counts active staff (for example &quot;4 active&quot;; it reads &quot;Loading…&quot; while the list loads). The list shows <strong>Name</strong>, <strong>Position</strong>, <strong>Role</strong>, <strong>Status</strong>, <strong>Mobile</strong>, <strong>Hire date</strong>. <strong>Search name or mobile</strong>, tick <strong>Include inactive</strong> to see former staff. The <strong>Setup to finish</strong> strip lists records missing something important (for example no pay rate) with a <strong>Fix</strong> link.</p><h3 id="add-a-person" tabindex="-1">Add a person <a class="header-anchor" href="#add-a-person" aria-label="Permalink to &quot;Add a person&quot;">​</a></h3><ol><li><strong>Add person</strong>.</li><li><strong>Identity</strong>: <strong>Full name</strong>, <strong>Email</strong> (their sign-in email, cannot be changed later here), <strong>Employee number</strong>, <strong>TIN</strong>, <strong>SSS</strong>.</li><li><strong>Tax address and birth date</strong>: <strong>Registered address</strong> (as on BIR Form 2316), <strong>ZIP code</strong>, <strong>Birth date</strong>.</li><li><strong>Role &amp; access</strong>: <strong>Role</strong> (Owner, Admin, Technician, Sales — only the owner changes roles), <strong>Home shop</strong>, and the permission switches <strong>Can canvass &amp; pay suppliers</strong>, <strong>Can open LOA PDF</strong>, <strong>Can see LOA pesos / job margin</strong>, <strong>Must clock</strong> (on for technicians, off for sales; the owner does not clock).</li><li><strong>Employment</strong>: <strong>Position</strong>, <strong>Department</strong>, <strong>Rest day</strong>, <strong>Hire date</strong> (required), <strong>PhilHealth</strong>, <strong>Pag-IBIG</strong>, and later <strong>Separation date</strong> / <strong>Separation reason</strong>.</li><li><strong>Contact</strong> and <strong>Emergency contact</strong>.</li><li><strong>Pay rate</strong>: <strong>Pay basis</strong> — <strong>Hourly</strong>, <strong>Daily</strong> (time-rated, paid from punches) or <strong>Monthly</strong> (fixed salary, less unpaid leave) — the rate, <strong>OT after hours</strong> and <strong>OT multiplier</strong>.</li><li><strong>Add person</strong>. An invite goes to their email (&quot;Waiting for first login&quot; until they sign in).</li></ol><h3 id="the-employee-record-hr-employee-directory-id" tabindex="-1">The employee record (<code>/hr/employee-directory/:id</code>) <a class="header-anchor" href="#the-employee-record-hr-employee-directory-id" aria-label="Permalink to &quot;The employee record (`/hr/employee-directory/:id`)&quot;">​</a></h3><ul><li><strong>Overview</strong> — identity, role and access, employment, contact.</li><li><strong>Pay</strong> — <strong>Current pay rate</strong> (<strong>Change rate</strong>; rates are dated so a raise starts on its own date), <strong>Rate history</strong>, <strong>Allowances</strong> (COLA, rice, transport… with amount, per period or day, taxable, effective dates).</li><li><strong>Loans / Cash advance</strong> — <strong>Add loan</strong> with kind, <strong>Principal</strong>, <strong>Per period</strong> instalment and <strong>Start period</strong>. Instalments come off each payroll run; <strong>Payments</strong> shows history; <strong>Cancel</strong> with a reason.</li><li><strong>Documents</strong> — <strong>Add document</strong> (Contract, Job offer, Government / Valid ID, COE request note, Other) and <strong>Download</strong>.</li><li><strong>Scorecards</strong> — KPI scorecards: <strong>New scorecard</strong> (Period, Year) → <strong>Create draft</strong> → score each KPI 1–5 with a comment → <strong>Save draft</strong> → <strong>Finalise</strong>. Hints (backjobs, punch days, NTE/NOD count, quota %) are context only. Finalized cards become visible to the employee; <strong>Reopen</strong> to change.</li><li><strong>Leave</strong> — balances and requests.</li><li><strong>History</strong> — every change to the record: field, old → new, who, when (audit trail).</li></ul><p><strong>More actions:</strong> <strong>Issue letter</strong> (Offer of employment, Certificate of employment, NTE, NOD, Warning letter, Quitclaim), <strong>Move open jobs to…</strong>, <strong>Deactivate</strong> / <strong>Reactivate</strong>. Deactivating someone with open jobs asks you to move them first (<strong>Move and deactivate</strong>) and cancels their pending leave.</p><p><strong>Final pay:</strong> set the <strong>Separation date</strong>, then in <strong>Payroll</strong> use the row menu <strong>Final pay</strong> for an estimate: last wages, pro-rated 13th month and unused SIL (SIL needs one year of service).</p><h2 id="_11-2-clock-kiosk-hr-clock-kiosk" tabindex="-1">11.2 Clock kiosk (<code>/hr/clock-kiosk</code>) <a class="header-anchor" href="#_11-2-clock-kiosk-hr-clock-kiosk" aria-label="Permalink to &quot;11.2 Clock kiosk (`/hr/clock-kiosk`)&quot;">​</a></h2><ol><li>On the shop tablet, sign in as owner and open <strong>HR › Clock kiosk</strong>.</li><li>The <strong>Desk kiosk</strong> lists everyone set to <strong>Must clock</strong>.</li><li>Staff tap their own name: &quot;Clocked out — tap to clock in&quot; / &quot;Clocked in — tap to clock out&quot;.</li><li>The kiosk asks to confirm (&quot;Clock in Int QA Tech? … will be clocked in for today (Oct 29, 2026).&quot;) and then shows &quot;Clocked in.&quot; The punch appears at once in <strong>HR › Attendance</strong> and on that person&#39;s <strong>Me › Time clock</strong>.</li></ol><p><img src="'+s+'" alt="Clock kiosk with one technician clocked in"></p><p>The kiosk does not check location. Phone clock-ins (Me › Time clock) do. Clock-in rules (map pin, allowed radius, photo, off-site punch with approval) are in <strong>Admin › Shop settings › Staff &amp; time</strong>.</p><h2 id="_11-3-attendance-off-site-punches-and-overtime-hr-attendance" tabindex="-1">11.3 Attendance: off-site punches and overtime (<code>/hr/attendance</code>) <a class="header-anchor" href="#_11-3-attendance-off-site-punches-and-overtime-hr-attendance" aria-label="Permalink to &quot;11.3 Attendance: off-site punches and overtime (`/hr/attendance`)&quot;">​</a></h2><p>The page opens on <strong>This week</strong> (Monday to Sunday, the same week Payroll uses). Use the arrows to move a week, <strong>This week</strong> to come back, or <strong>Custom range</strong>.</p><h3 id="register" tabindex="-1">Register <a class="header-anchor" href="#register" aria-label="Permalink to &quot;Register&quot;">​</a></h3><p>Every punch: <strong>Name</strong>, <strong>Branch</strong>, <strong>In</strong> (with <strong>In photo</strong>), <strong>Out</strong> (with <strong>Out photo</strong>), <strong>Hours</strong>, <strong>Status</strong>. Filter <strong>All / Pending / Approved / Rejected</strong> and by <strong>Staff</strong>. <strong>Download CSV</strong> from the menu.</p><ul><li><strong>Off-site punches</strong> show the staff reason and are <strong>Pending</strong>. Press <strong>Approve</strong> or <strong>Reject</strong> (optional note). Only approved off-site time is paid.</li><li><strong>Punch for…</strong> — enter a punch for someone (Manila times; leave clock-out empty to keep the shift open).</li><li><strong>Close</strong> an open punch with the real <strong>Clock out</strong> time and a <strong>Reason</strong>.</li></ul><h3 id="ot-to-approve" tabindex="-1">OT to approve <a class="header-anchor" href="#ot-to-approve" aria-label="Permalink to &quot;OT to approve&quot;">​</a></h3><p>Overtime requests and time past shift end. Each row: <strong>Name</strong>, <strong>Date</strong>, <strong>Source</strong>, <strong>Hours</strong>, <strong>Status</strong>.</p><ol><li>Press <strong>Approve</strong> and set <strong>Hours to approve</strong> (can be fewer than claimed) and a note, or <strong>Reject</strong>.</li><li>Approved OT flows into payroll at the OT multiplier. Pay never exceeds punched hours.</li></ol><p>Whether admins may also approve OT is a payroll setting (<strong>Admins can approve OT</strong>).</p><h2 id="_11-4-leave-approvals-hr-leave" tabindex="-1">11.4 Leave approvals (<code>/hr/leave</code>) <a class="header-anchor" href="#_11-4-leave-approvals-hr-leave" aria-label="Permalink to &quot;11.4 Leave approvals (`/hr/leave`)&quot;">​</a></h2><p>Top tiles: <strong>Vacation remaining</strong>, <strong>Sick remaining</strong>, <strong>Unpaid taken</strong>, <strong>SIL remaining</strong>.</p><h3 id="decide-a-request" tabindex="-1">Decide a request <a class="header-anchor" href="#decide-a-request" aria-label="Permalink to &quot;Decide a request&quot;">​</a></h3><ol><li>Under <strong>Needs a decision</strong>, review staff, dates (half days show AM/PM), type, days and note.</li><li>Press <strong>Approve</strong>. If the person has open jobs, the <strong>Approve leave</strong> dialog says how many (&quot;Int QA Tech has 3 open job(s). Move any of them, or keep them as they are.&quot;) and lists each job (plate, reference, who else is on it). For each choose <strong>Reassign to…</strong> a colleague or leave it as it is. Then <strong>Approve leave</strong> (or <strong>Not yet</strong>). Released and closed jobs are not listed.</li><li>Or press <strong>Reject</strong>. A decided request can still be cancelled with a reason.</li></ol><h3 id="set-allotments" tabindex="-1">Set allotments <a class="header-anchor" href="#set-allotments" aria-label="Permalink to &quot;Set allotments&quot;">​</a></h3><p>Menu <strong>Set days</strong> → <strong>Set allotment</strong>: <strong>Person</strong>, <strong>Year</strong>, <strong>Type</strong> (Vacation, Sick, Service incentive (SIL)), <strong>Days</strong> → <strong>Save allotment</strong>. <strong>Team balances</strong> shows days left / allotted for everyone (Unpaid shows days taken).</p><p><img src="'+a+'" alt="Leave approvals with Needs a decision, Team balances and History"></p><p><strong>Add leave</strong> records leave on someone&#39;s behalf (for example a phoned-in sick day).</p><h2 id="_11-5-payroll-hr-payroll" tabindex="-1">11.5 Payroll (<code>/hr/payroll</code>) <a class="header-anchor" href="#_11-5-payroll-hr-payroll" aria-label="Permalink to &quot;11.5 Payroll (`/hr/payroll`)&quot;">​</a></h2><p>Payroll is computed from closed punches and dated pay rates. Payout happens outside the app.</p><h3 id="run-a-period" tabindex="-1">Run a period <a class="header-anchor" href="#run-a-period" aria-label="Permalink to &quot;Run a period&quot;">​</a></h3><ol><li>Choose the period. It opens on <strong>This week</strong> (Monday to Sunday, like Attendance); use <strong>Custom range</strong> for a semi-monthly or monthly run. The register previews each person: <strong>Basis</strong>, <strong>Rate</strong>, <strong>Regular hours</strong>, <strong>OT hours</strong>, <strong>OT pay</strong>, <strong>Days paid</strong>, <strong>Holiday pay</strong>, <strong>Rest day</strong>, <strong>Night diff (NSD)</strong>, <strong>Premium pay</strong>, <strong>COLA / allowances</strong>, <strong>Loans / CA</strong>, <strong>Amount</strong>, <strong>Deductions</strong>, <strong>Net</strong>.</li><li>Read the warnings: open clock-ins (not paid until closed — <strong>Review in Attendance</strong>), pending OT, unpaid bonuses, staff without a pay rate.</li><li>Statutory deductions: choose <strong>Semi-monthly (½)</strong> or <strong>Full month</strong>, press <strong>Suggest</strong> (per row) or <strong>Suggest all</strong> for SSS, PhilHealth, Pag-IBIG and WHT, check them, edit <strong>Other</strong>, then <strong>Save</strong> / <strong>Save all</strong>.</li><li>Use the row menu for adjustments — each needs a <strong>Reason</strong> and is logged: <ul><li><strong>Edit premium</strong>, <strong>Edit allowances</strong>, <strong>Edit loan instalment</strong>, <strong>Rate</strong>.</li><li><strong>Day pay override</strong> — pick the <strong>Work date</strong> and <strong>Mode</strong>: <strong>Full day</strong>, <strong>Half day</strong>, <strong>None</strong> or <strong>Custom amount</strong> (with <strong>Custom amount (PHP)</strong>). A <strong>Reason</strong> is required. It is allowed only while the period is <strong>unlocked</strong>, is owner/admin only, and is written to the HR change log. <strong>Clear override</strong> restores the calculated pay.</li></ul></li><li><strong>Holidays &amp; premiums</strong>: add regular/special holidays (<strong>Copy last year</strong>), and set holiday, rest day, night-diff and OT premium percents, shift end, OT grace and monthly day divisor.</li></ol><h3 id="lock-and-pay" tabindex="-1">Lock and pay <a class="header-anchor" href="#lock-and-pay" aria-label="Permalink to &quot;Lock and pay&quot;">​</a></h3><ol><li>Choose <strong>Shop to lock</strong> and press <strong>Lock period</strong>. Deductions freeze (&quot;Post any correction as an adjustment in the next period.&quot;).</li><li><strong>Print payslips</strong> or open <strong>Payslip</strong> per row and <strong>Issue payslip</strong>. Staff then see it in <strong>Me › My payslip</strong>.</li><li><strong>Export CSV</strong> for the bank or bookkeeper.</li><li>A locked period never changes; the owner can only <strong>Void run</strong>.</li></ol><h3 id="_13th-month-calculator" tabindex="-1">13th-month calculator <a class="header-anchor" href="#_13th-month-calculator" aria-label="Permalink to &quot;13th-month calculator&quot;">​</a></h3><p>Pick the <strong>Calendar year</strong> and <strong>Run</strong>. Each row shows <strong>Basic auto</strong>, an optional <strong>Override</strong> of basic earned, <strong>Basic used</strong> and <strong>13th month</strong> (basic earned ÷ 12). <strong>Save override</strong>, <strong>Export CSV</strong>, <strong>Print summary</strong>. It is an estimate for the owner to verify, not a BIR filing.</p><p><img src="'+i+'" alt="Payroll register with Lock period and the Day pay override dialog"></p><h2 id="_11-6-announcements-hr-announcements" tabindex="-1">11.6 Announcements (<code>/hr/announcements</code>) <a class="header-anchor" href="#_11-6-announcements-hr-announcements" aria-label="Permalink to &quot;11.6 Announcements (`/hr/announcements`)&quot;">​</a></h2><ol><li><strong>New announcement</strong>: <strong>Title</strong>, <strong>Body</strong>, <strong>Start date</strong>, <strong>End date</strong>, <strong>Active</strong>.</li><li><strong>Post</strong>.</li></ol><p>Active announcements inside their dates show on the Dashboard for sales and on My jobs for technicians. <strong>Edit</strong> or <strong>Remove</strong> any time.</p><h2 id="_11-7-documents-hub-hr-documents" tabindex="-1">11.7 Documents Hub (<code>/hr/documents</code>) <a class="header-anchor" href="#_11-7-documents-hub-hr-documents" aria-label="Permalink to &quot;11.7 Documents Hub (`/hr/documents`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Template</th><th>Status</th><th>What it produces</th></tr></thead><tbody><tr><td><strong>Notice to explain</strong> (NTE)</td><td>Available</td><td>Incident, rule cited (defaults to Article 297), response window, hearing date and venue, signature blanks</td></tr><tr><td><strong>Notice of decision</strong> (NOD)</td><td>Available</td><td>Outcome: <strong>Warning</strong>, <strong>Suspension</strong> (days) or <strong>Termination</strong>, effective date, decision summary</td></tr><tr><td><strong>Warning letter</strong></td><td>Available</td><td><strong>Verbal warning documented</strong>, <strong>First written warning</strong> or <strong>Final written warning</strong>, incident, rule violated, corrective action, consequence, related NTE</td></tr><tr><td><strong>Quitclaim and release</strong></td><td>Available</td><td>Separation acknowledgment with <strong>Separation date</strong> and a typed <strong>Final pay (PHP)</strong></td></tr><tr><td><strong>BIR Form 2316</strong></td><td>Available</td><td>Data sheet for one employee and year from <strong>locked</strong> payroll runs</td></tr><tr><td>BIR Form 2307</td><td>Coming soon</td><td>—</td></tr></tbody></table><p><strong>Generate a document</strong></p><ol><li>Press <strong>Generate</strong> on the template.</li><li>Pick the <strong>Staff</strong>; worker name, position, IDs and shop letterhead fill in.</li><li>Complete the template fields and check the preview.</li><li><strong>Save to employment docs</strong> (files it on the person&#39;s <strong>Documents</strong> tab), <strong>Download PDF</strong> or <strong>Print</strong>.</li></ol><p><strong>BIR 2316:</strong> choose <strong>Employee</strong> and <strong>Year</strong>. The sheet lists the locked runs used and names anything missing (TIN, address, ZIP, birth date). Enter the amounts HR keeps (13th month and other benefits, de minimis, other non-taxable, previous employer amounts), then <strong>Download PDF</strong> or <strong>Print</strong>. It is a data sheet to copy into the official form or eBIRForms; it does not file anything.</p><p><strong>Employment papers:</strong> the <strong>Offer of employment</strong> and <strong>Certificate of employment</strong> are issued from the person&#39;s record in <strong>Directory</strong> (<strong>Issue letter</strong>), not from this hub. Together with the contract and ID uploads they make up the employee&#39;s employment file. A single bundled &quot;employment pack&quot; is not a separate template in this version.</p>',50)])])}const k=o(l,[["render",g]]);export{y as __pageData,k as default};
